 "content": "def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    # The two markers sharing a row form the main horizontal bar.
    rows = {}
    for r, c in points:
        rows.setdefault(r, []).append(c)
    base_rows = [r for r, cols in rows.items() if len(cols) >= 2]
    if not base_rows:
        return out
    base = base_rows[0]
    left, right = min(rows[base]), max(rows[base])
    for c in range(left + 1, right):
        if out[base][c] == 0:
            out[base][c] = 3
    # Join every other marker to the bar with a vertical branch at its column.
    for r, c in points:
        if r == base:
            continue
        lo, hi = sorted((r, base))
        for rr in range(lo + 1, hi):
            if out[rr][c] == 0:
                out[rr][c] = 3
    return out
